import React from 'react';
import iconMap from './iconMap.generated';
import { toCss } from './style';

/**
 * Material icon by its kebab-case name (e.g. "calendar-month").
 * Icons come from `react-icons/md`; the map is generated by
 * `npm run icons` so only the icons the app uses are bundled.
 */
export function MaterialIcons({ name, size = 24, color, style }) {
  const Icon = iconMap[name];
  const css = toCss(style);
  if (!Icon) {
    if (import.meta.env?.DEV) console.warn(`[icons] Unknown Material icon "${name}"`);
    return <span className="rn-icon" style={{ width: size, height: size, ...css }} aria-hidden="true" />;
  }
  return <Icon className="rn-icon" size={size} color={color} style={css} aria-hidden="true" />;
}
export default MaterialIcons;
